import{_ as t}from"./chunks/1776153628712.v2-8gJzS.js";import{_ as i,o as a,c as n,a2 as o}from"./chunks/framework.CdjpmwdR.js";const g=JSON.parse('{"title":"Logseq Migration Scoring: Five Dimensions, Three Pipelines","description":"Evaluate old notes across five dimensions and route them into A/B/C migration pipelines with thresholds, CSV fields, and calibration steps for execution.","frontmatter":{"category":"domain","title":"Logseq Migration Scoring: Five Dimensions, Three Pipelines","date":"2026-04-13","description":"Evaluate old notes across five dimensions and route them into A/B/C migration pipelines with thresholds, CSV fields, and calibration steps for execution.","tags":["domain","logseq","migration","knowledge-management"]},"headers":[],"relativePath":"en/blogs/2026/202604-logseq-scoring-overview.md","filePath":"en/blogs/2026/202604-logseq-scoring-overview.md"}'),s={name:"en/blogs/2026/202604-logseq-scoring-overview.md"};function r(l,e,d,c,h,u){return a(),n("div",null,[...e[0]||(e[0]=[o(`<p>After building Brains (the LLM Wiki), the first task was to revisit my Logseq vault and extract remaining value. The hardest part of migrating old Logseq notes isn&#39;t deciding which content looks useful by feel; it&#39;s creating a repeatable, auditable process. I designed a scoring mechanism where agents rate content on five review dimensions, then classify notes into three lanes by score thresholds: ingest now, summarize later, or drop. This replaces ad-hoc judgment with a process that can be audited and calibrated.</p><p>Execution rule: high-value, strongly relevant, reusable items go to Lane A; temporarily useful but not worth immediate refinement go to Lane B; low-score, duplicate, or off-topic items go to Lane C.</p><h2 id="the-five-scoring-dimensions-—-what-each-filters-for" tabindex="-1">The five scoring dimensions — what each filters for <a class="header-anchor" href="#the-five-scoring-dimensions-—-what-each-filters-for" aria-label="Permalink to &quot;The five scoring dimensions — what each filters for&quot;">​</a></h2><p>The rubric maps to five fields: <code>goal_alignment</code>, <code>reusability</code>, <code>uniqueness</code>, <code>insight_density</code>, and <code>maintainability</code>. They look like metrics but actually answer five personalized questions.</p><table tabindex="0"><thead><tr><th>Dimension</th><th>What it checks</th><th>Signals of high score</th><th>Signals of low score</th></tr></thead><tbody><tr><td>goal_alignment</td><td>Does it serve current goals?</td><td>Core theme, directly outputable</td><td>Off-topic, unrelated</td></tr><tr><td>reusability</td><td>Can it be reused across contexts?</td><td>Methods, rules, frameworks</td><td>One-off note, strong context dependency</td></tr><tr><td>uniqueness</td><td>Is it duplicate work?</td><td>Unique expression, cases, structure</td><td>Repeated excerpts, variants</td></tr><tr><td>insight_density</td><td>Does the piece contain judgement?</td><td>Conclusions, boundaries, recommendations</td><td>Only material, no distillation</td></tr><tr><td>maintainability</td><td>Will it be easy to maintain?</td><td>Clear boundaries, easy to reference</td><td>Diffuse theme, high maintenance cost</td></tr></tbody></table><div class="language-mermaid vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">mermaid</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">flowchart TD</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">  score[five-dimension scoring] --&gt; check{duplicate / off-goal?}</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">  check -- yes --&gt; laneC[Lane C: Drop]</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">  check -- no --&gt; total{total_score &gt;= 18?}</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">  total -- no --&gt; mid{11-17?}</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">  total -- yes --&gt; goal{goal_alignment &gt;= 4?}</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">  goal -- yes --&gt; laneA[Lane A: Ingest-Now]</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">  mid -- yes --&gt; laneB[Lane B: Summarize-Later]</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">  goal -- no --&gt; laneB</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">  mid -- no --&gt; laneC</span></span></code></pre></div><h3 id="_1-goal-alignment-—-does-this-note-serve-current-knowledge-goals" tabindex="-1">1. goal_alignment — does this note serve current knowledge goals? <a class="header-anchor" href="#_1-goal-alignment-—-does-this-note-serve-current-knowledge-goals" aria-label="Permalink to &quot;1. goal_alignment — does this note serve current knowledge goals?&quot;">​</a></h3><p>This dimension asks whether the note aligns with the migration goals. Priority goes to reusable methods, frameworks, and long-lived knowledge, so core themes naturally score higher than generic notes. A simple test: can the note reliably serve the knowledge base&#39;s goals or future outputs after migration?</p><p>Strongly relevant files (e.g., <code>DDD.md</code>, <code>4+1 View Model.md</code>, <code>analysis_tools___MECE.md</code>, <code>architecture_governance.md</code>) sit closer to top priority. Light-weight, personal, or marginal notes score lower.</p><h3 id="_2-reusability-—-can-this-note-be-reused-across-contexts" tabindex="-1">2. reusability — can this note be reused across contexts? <a class="header-anchor" href="#_2-reusability-—-can-this-note-be-reused-across-contexts" aria-label="Permalink to &quot;2. reusability — can this note be reused across contexts?&quot;">​</a></h3><p>Reusability checks whether the note stands on its own across contexts. How well an author wrote it matters less than whether the content describes transferable methods, frameworks, or decision rules. DDD breakdowns, architecture comparisons, and cognitive bias summaries usually fit the knowledge layer; scattered QA, ephemeral ideas, and meeting fragments belong to Lane B.</p><p>Lane B is designed as &quot;summary bundles&quot; to recognize: some materials have thematic value but aren’t worth refining one-by-one. They should not be dropped, but they also shouldn’t consume Lane A capacity.</p><h3 id="_3-uniqueness-—-is-this-note-duplicate-work" tabindex="-1">3. uniqueness — is this note duplicate work? <a class="header-anchor" href="#_3-uniqueness-—-is-this-note-duplicate-work" aria-label="Permalink to &quot;3. uniqueness — is this note duplicate work?&quot;">​</a></h3><p>Uniqueness addresses redundancy in migration. The plan creates <code>duplicate-clusters.md</code> to group similar notes, then determine whether an entry is canonical or a variant.</p><table tabindex="0"><thead><tr><th>Duplicate cluster</th><th>Typical problem</th><th>Handling approach</th></tr></thead><tbody><tr><td>DDD family</td><td>multiple expansions</td><td>Find canonical source</td></tr><tr><td>architecture style comparisons</td><td>repeated comparison dims</td><td>Merge into a thematic bundle</td></tr><tr><td>cognition micro-bias notes</td><td>fragmented but similar</td><td>Aggregate then distill</td></tr><tr><td>overlapping workshop Q&amp;A notes</td><td>overlapping Q&amp;A</td><td>Keep the most complete version</td></tr></tbody></table><ul><li>If a note contains expression, cases, or structure not found elsewhere, it is more unique.</li><li>If it is a shorthand, duplicate excerpt, or partial expansion of another note, down-weight uniqueness.</li></ul><p>Without this step, the migrated knowledge base inherits the old system&#39;s redundancy.</p><h3 id="_4-insight-density-—-does-the-piece-contain-real-judgement-per-unit-length" tabindex="-1">4. insight_density — does the piece contain real judgement per unit length? <a class="header-anchor" href="#_4-insight-density-—-does-the-piece-contain-real-judgement-per-unit-length" aria-label="Permalink to &quot;4. insight_density — does the piece contain real judgement per unit length?&quot;">​</a></h3><p>Insight density measures &quot;actionable judgement&quot; per unit length. High-density notes contain conclusions, boundaries, or actionable recommendations; low-density notes are often just titles, concepts, or excerpts. Those belong in Lane B&#39;s thematic summaries as source material.</p><p>The migration plan follows a &quot;synthesis → evidence → pages&quot; path to increase insight density: merge raw materials, distill defensible judgements, and then move items into the long-lived knowledge layer.</p><h3 id="_5-maintainability-—-will-it-be-easy-to-maintain-once-moved" tabindex="-1">5. maintainability — will it be easy to maintain once moved? <a class="header-anchor" href="#_5-maintainability-—-will-it-be-easy-to-maintain-once-moved" aria-label="Permalink to &quot;5. maintainability — will it be easy to maintain once moved?&quot;">​</a></h3><p>This dimension prevents the knowledge base from becoming heavier over time. Maintainable content has clear boundaries, stable structure, and is easy to merge and reference; hard-to-maintain content is diffuse, broad, and strongly context-dependent. The plan requires <code>inventory.csv</code> to record <code>primary_category</code>, <code>secondary_category</code>, and <code>decision_reason</code> to make maintenance costs explicit.</p><h2 id="threshold-rules-—-throughput-control" tabindex="-1">Threshold rules — throughput control <a class="header-anchor" href="#threshold-rules-—-throughput-control" aria-label="Permalink to &quot;Threshold rules — throughput control&quot;">​</a></h2><p>The plan specifies thresholds:</p><ul><li><code>total_score &gt;= 18</code> and <code>goal_alignment &gt;= 4</code> → Lane A</li><li><code>11-17</code> → Lane B</li><li><code>&lt;= 10</code> or duplicate / off-goal → Lane C</li></ul><p>I emphasize that Lane A additionally requires <code>goal_alignment &gt;= 4</code>. This enforces the hierarchy: first, serve current goals; second, evaluate overall value.</p><h3 id="lane-a-ingest-now" tabindex="-1">Lane A: ingest now <a class="header-anchor" href="#lane-a-ingest-now" aria-label="Permalink to &quot;Lane A: ingest now&quot;">​</a></h3><p>Lane A corresponds to Ingest-Now. Materials here are high-value, strongly goal-aligned, and worth immediate refinement and production line treatment.</p><p>Typical candidates include seed DDD, architecture patterns, methods, and core cognitive notes. They are staged into <code>raws/*-core-synthesis.md</code> and <code>raws/*-core-evidence.md</code> before promotion to <code>pages/DDD.md</code>, <code>pages/architecture-patterns.md</code>, or <code>pages/decision-analysis-methods.md</code>. Lane A means: enter the production line.</p><h3 id="lane-b-summarize-later" tabindex="-1">Lane B: summarize later <a class="header-anchor" href="#lane-b-summarize-later" aria-label="Permalink to &quot;Lane B: summarize later&quot;">​</a></h3><p>Lane B corresponds to Summarize-Later. Scores in 11–17 range indicate items worth keeping but not worth immediate refinement.</p><p>These items are bundled by topic, e.g.: <code>raws/DDD-extended-notes-summary.md</code>, <code>raws/architecture-styles-comparison-summary.md</code>, <code>raws/cognitive-bias-and-heuristics-summary.md</code>.</p><p>The rule is practical: some items are valuable mainly in groups. Refining them individually is costlier than the benefit.</p><h3 id="lane-c-record-and-review" tabindex="-1">Lane C: record and review <a class="header-anchor" href="#lane-c-record-and-review" aria-label="Permalink to &quot;Lane C: record and review&quot;">​</a></h3><p>Lane C corresponds to Drop, but the plan treats it conservatively. Items with <code>&lt;= 10</code> or duplicate/off-goal may enter Lane C, but any physical deletion must wait for a full review and explicit confirmation.</p><p>Lane C is a ledgered quarantine:</p><ul><li>Record why an item was deprioritized.</li><li>Tag whether it&#39;s a duplicate, off-topic, or low-value.</li><li>Revisit deletions only after the full classification is complete.</li></ul><p>This prevents premature deletion when scoring rules are still being calibrated.</p><h2 id="execution-thread-scoring-distillation-and-ingestion-into-one-line" tabindex="-1">Execution: thread scoring, distillation, and ingestion into one line <a class="header-anchor" href="#execution-thread-scoring-distillation-and-ingestion-into-one-line" aria-label="Permalink to &quot;Execution: thread scoring, distillation, and ingestion into one line&quot;">​</a></h2><p>To make this operational, the crucial factor is whether each step leads to concrete actions: write-backs, auditable records, and human review where needed.</p><ol><li>Dump all items into <code>inventory.csv</code>. <ul><li>Record not only filenames, but <code>filename</code>, <code>primary_category</code>, <code>secondary_category</code>, <code>goal_alignment</code>, <code>reusability</code>, <code>uniqueness</code>, <code>insight_density</code>, <code>maintainability</code>, <code>total_score</code>, <code>lane</code>, <code>duplicate_cluster</code>, <code>decision_reason</code>, and <code>status</code>. That way decisions operate on data, not impressions.</li></ul></li><li>Wrap the CSV into a CRUD interface via Python scripts. <ul><li>I avoid letting agents directly edit the table; instead, encode interaction rules in prompts so agents read, compute, and write according to rules.</li><li>In short: program the rules, then let agents follow them to reduce ad-hoc deviations.</li></ul></li><li>Score in batches of 20 items. <ul><li>Agents analyze each batch and use the Python script to write scores, categories, lanes, and reasons back to the CSV.</li><li>The first round&#39;s goal is coverage: score everything, don&#39;t refine. After each batch, output grouped results and surface items needing manual confirmation, especially boundary cases, duplicate clusters, and disputed items.</li></ul></li><li>After initial screening, perform distillation in batches of 20. <ul><li>This round focuses on converting surviving materials into <code>raws</code>-level source materials that the knowledge base can accept.</li><li>Agents analyze, scripts persist results, and humans confirm edge cases; the outcome is not polished notes but screened and synthesis-ready raw materials.</li></ul></li><li>Finally, after distillation completes, run <code>/kn-ingest</code>. <ul><li>This step ingests curated <code>raws</code> into the knowledge base; only now does scoring, distillation, and ingestion form a closed loop.</li></ul></li></ol><p>At the end, I obtained ten highly distilled, well-structured, and reusable core notes (Lane A).</p><h2 id="example" tabindex="-1">Example <a class="header-anchor" href="#example" aria-label="Permalink to &quot;Example&quot;">​</a></h2><p><img src="`+t+'" alt="Theme Wave 01"></p>',44)])])}const b=i(s,[["render",r]]);export{g as __pageData,b as default};
